class Solution {
public:
    int calculateTime(string keyboard, string word) {
        vector<int> pos(26);
        for (int i = 0; i < 26; ++i) pos[keyboard[i] - 'a'] = i;
        int curr = 0, total = 0;
        for (char c : word) {
            int nxt = pos[c - 'a'];
            total += abs(nxt - curr);
            curr = nxt;
        }
        return total;
    }
};

class Solution {
    public int calculateTime(String keyboard, String word) {
        int[] pos = new int[26];
        for (int i = 0; i < 26; i++) pos[keyboard.charAt(i) - 'a'] = i;
        int curr = 0, total = 0;
        for (char c : word.toCharArray()) {
            int nxt = pos[c - 'a'];
            total += Math.abs(nxt - curr);
            curr = nxt;
        }
        return total;
    }
}

var calculateTime = function(keyboard, word) {
    const pos = new Array(26);
    const code = (c) => c.charCodeAt(0) - 97;
    for (let i = 0; i < 26; i++) pos[code(keyboard[i])] = i;
    let curr = 0, total = 0;
    for (const c of word) {
        const nxt = pos[code(c)];
        total += Math.abs(nxt - curr);
        curr = nxt;
    }
    return total;
};
